# Analysis

I need to:
1. Create a unified selector component that works for both LLM models and profiles
2. Move the LLM model selector from the toolbar to before the profile selector
3. Add text filtering to both selectors
4. Implement alphabetical sorting
5. Follow the VueDeveloper profile structure

Let me create the necessary files:

## Implementation

```vue src/components/chat/Selector.vue
<script setup>
</script>

<template>
  <div class="relative">
    <!-- Trigger button -->
    <button 
      class="btn btn-sm btn-ghost gap-2"
      @click.stop="toggleGrid"
      :title="buttonTitle"
    >
      <i :class="icon"></i>
      <span class="text-xs font-semibold">{{ label }}</span>

      <!-- Selected item badge for single selection -->
      <div v-if="selectedItem && isSingleSelect" class="badge badge-sm gap-1 badge-primary">
        <img 
          v-if="selectedItem.avatar"
          :src="selectedItem.avatar"
          :alt="selectedItem.name"
          class="w-3 h-3 rounded-full object-cover"
        />
        <span class="truncate text-xs">{{ selectedItem.name }}</span>
      </div>

      <!-- Active profile badges for multiple selection -->
      <div v-else-if="activeItems.length && !isSingleSelect" class="flex flex-wrap gap-1">
        <div 
          v-for="item in activeItems"
          :key="item.name"
          class="badge badge-sm gap-1 badge-primary"
          :title="item.description"
        >
          <img 
            v-if="item.avatar"
            :src="item.avatar"
            :alt="item.name"
            class="w-3 h-3 rounded-full object-cover"
          />
          <span class="truncate text-xs">{{ item.name }}</span>
        </div>
      </div>
    </button>

    <!-- Full-width grid panel above trigger -->
    <div 
      v-show="showGrid"
      class="absolute left-0 bottom-full mb-2 bg-base-200 rounded-lg border border-base-300 shadow-lg z-50 w-screen max-w-full p-4"
      @click.stop
    >
      <div class="text-sm font-semibold mb-3">{{ label }}</div>

      <!-- Search filter input -->
      <input 
        v-model="filterText"
        type="text"
        placeholder="Type to filter..."
        class="input input-sm input-bordered w-full mb-3"
        @click.stop
      />

      <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 max-h-64 overflow-y-auto">
        <div 
          v-for="item in filteredAndSorted"
          :key="item.name"
          class="flex flex-col items-center gap-2 p-3 rounded-lg cursor-pointer transition-all hover:bg-base-300"
          :class="isItemSelected(item.name) ? 'bg-primary text-primary-content' : 'bg-base-100'"
          @click="selectItem(item)"
          :title="item.description"
        >
          <div class="relative">
            <img 
              v-if="item.avatar"
              :src="item.avatar"
              :alt="item.name"
              class="w-10 h-10 rounded-full object-cover"
            />
            <div 
              v-else
              class="w-10 h-10 rounded-full bg-base-300 flex items-center justify-center"
            >
              <i class="fa-solid fa-user text-xs"></i>
            </div>
            <div 
              v-if="isItemSelected(item.name)"
              class="absolute -top-1 -right-1 bg-success text-white rounded-full w-5 h-5 flex items-center justify-center text-xs font-bold"
            >
              ✓
            </div>
          </div>
          <span class="text-xs font-medium text-center truncate w-full">{{ item.name }}</span>
        </div>
      </div>

      <div v-if="selectedItems.length > 0" class="text-xs text-base-content/60 mt-3 border-t border-base-300 pt-3">
        {{ selectedCountText }}
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    items: {
      type: Array,
      default: () => []
    },
    selectedItems: {
      type: Array,
      default: () => []
    },
    label: {
      type: String,
      required: true
    },
    icon: {
      type: String,
      required: true
    },
    isSingleSelect: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      internalSelected: [],
      showGrid: false,
      filterText: ''
    }
  },
  computed: {
    filteredAndSorted() {
      const filtered = (this.items || []).filter(item =>
        item.name.toLowerCase().includes(this.filterText.toLowerCase())
      )
      return filtered.sort((a, b) => a.name.localeCompare(b.name))
    },
    activeItems() {
      return (this.items || []).filter(item =>
        this.internalSelected.includes(item.name)
      )
    },
    selectedItem() {
      if (!this.isSingleSelect || this.internalSelected.length === 0) return null
      return (this.items || []).find(item => item.name === this.internalSelected[0])
    },
    buttonTitle() {
      if (this.isSingleSelect && this.selectedItem) {
        return this.selectedItem.name
      }
      if (this.activeItems.length > 0) {
        return `${this.activeItems.length} item(s) selected`
      }
      return `Select ${this.label.toLowerCase()}`
    },
    selectedCountText() {
      if (this.isSingleSelect) {
        return this.selectedItem ? `Selected: ${this.selectedItem.name}` : 'None selected'
      }
      return `${this.internalSelected.length} item(s) selected`
    }
  },
  watch: {
    selectedItems: {
      handler(newVal) {
        this.internalSelected = newVal.map(item => typeof item === 'string' ? item : item.name)
      },
      deep: true
    }
  },
  mounted() {
    this.internalSelected = this.selectedItems.map(item => typeof item === 'string' ? item : item.name)
    document.addEventListener('click', this.handleDocumentClick)
  },
  unmounted() {
    document.removeEventListener('click', this.handleDocumentClick)
  },
  methods: {
    toggleGrid() {
      this.showGrid = !this.showGrid
      if (this.showGrid) {
        this.filterText = ''
      }
    },
    isItemSelected(itemName) {
      return this.internalSelected.includes(itemName)
    },
    selectItem(item) {
      if (this.isSingleSelect) {
        this.internalSelected = [item.name]
        this.showGrid = false
        this.$emit('update:selected-items', [item])
      } else {
        const index = this.internalSelected.indexOf(item.name)
        if (index > -1) {
          this.internalSelected.splice(index, 1)
        } else {
          this.internalSelected.push(item.name)
        }
        const updatedItems = (this.items || []).filter(i =>
          this.internalSelected.includes(i.name)
        )
        this.$emit('update:selected-items', updatedItems)
      }
    },
    handleDocumentClick(event) {
      if (!this.$el.contains(event.target)) {
        this.showGrid = false
      }
    }
  }
}
</script>
```

