```vue src/components/chat/ChatLLMModelSelector.vue
<script setup>
import Selector from './Selector.vue'
</script>

<template>
  <Selector
    :items="formattedModels"
    :selected-items="selectedModelItem"
    label="Model"
    icon="fa-solid fa-brain"
    :is-single-select="true"
    @update:selected-items="onModelSelected"
  />
</template>

<script>
export default {
  props: {
    selectedModel: String,
    models: {
      type: Array,
      default: () => []
    }
  },
  emits: ['model-changed'],
  computed: {
    formattedModels() {
      return (this.models || []).map(model => ({
        name: model.name,
        description: model.ai_model || model.description,
        avatar: null
      }))
    },
    selectedModelItem() {
      if (!this.selectedModel) return []
      const model = this.formattedModels.find(m => m.name === this.selectedModel)
      return model ? [model] : []
    }
  },
  methods: {
    onModelSelected(selectedItems) {
      const modelName = selectedItems.length > 0 ? selectedItems[0].name : ''
      this.$emit('model-changed', modelName)
    }
  }
}
</script>
```

```vue src/components/chat/ChatInputBox.vue
<script setup>
import ChatInputToolbar from './ChatInputToolbar.vue'
</script>

<template>
  <div class="flex flex-col gap-2 px-2 py-2 bg-base-100 rounded-md border border-base-300">
    <!-- Model and Profile Selectors -->
    <div class="flex gap-2 items-center flex-wrap" v-if="!readOnly">
      <ChatLLMModelSelector
        :selected-model="selectedModel"
        :models="aiModels"
        @model-changed="$emit('model-changed', $event)"
        v-if="aiModels?.length"
      />

      <ChatProfileSelector
        :profiles="profiles"
        :selected-profiles="selectedProfiles"
        @update:selected-profiles="$emit('profiles-selected', $event)"
        v-if="profiles?.length"
      />
    </div>

    <!-- Editor area -->
    <div class="relative">
      <textarea
        ref="editor"
        class="textarea textarea-bordered w-full min-h-24"
        placeholder="Type your message..."
        @keydown="$emit('keydown', $event)"
        @paste="$emit('paste', $event)"
        @drop="$emit('drop', $event)"
      ></textarea>
    </div>

    <!-- Toolbar with action buttons -->
    <ChatInputToolbar
      :waiting="waiting"
      :is-editing="isEditing"
      :is-voice-session="isVoiceSession"
      :searching="searching"
      :has-test-script="hasTestScript"
      :selected-model="selectedModel"
      :ai-models="aiModels"
      :images="images"
      :voice-language-label="voiceLanguageLabel"
      @send="$emit('send')"
      @add-message="$emit('add-message')"
      @search-message="$emit('search-message')"
      @cancel-edit="$emit('cancel-edit')"
      @model-changed="$emit('model-changed', $event)"
      @toggle-search="$emit('toggle-search')"
      @hide-all="$emit('hide-all')"
      @attach-files="$emit('attach-files')"
      @test-project="$emit('test-project')"
      @toggle-voice="$emit('toggle-voice')"
      @remove-image="$emit('remove-image', $event)"
      @preview-image="$emit('preview-image', $event)"
    />
  </div>
</template>

<script>
import ChatLLMModelSelector from './ChatLLMModelSelector.vue'
import ChatProfileSelector from './ChatProfileSelector.vue'

export default {
  components: {
    ChatLLMModelSelector,
    ChatProfileSelector
  },
  props: {
    waiting: Boolean,
    isEditing: Boolean,
    isVoiceSession: Boolean,
    searching: Boolean,
    readOnly: Boolean,
    hasTestScript: Boolean,
    selectedModel: String,
    aiModels: { type: Array, default: () => [] },
    images: { type: Array, default: () => [] },
    voiceLanguageLabel: String,
    profiles: { type: Array, default: () => [] },
    selectedProfiles: { type: Array, default: () => [] }
  },
  emits: [
    'send', 'add-message', 'search-message', 'cancel-edit', 'model-changed',
    'toggle-search', 'hide-all', 'attach-files', 'test-project',
    'toggle-voice', 'remove-image', 'preview-image', 'keydown', 'paste',
    'drop', 'profiles-selected'
  ],
  methods: {
    getEditorText() {
      return this.$refs.editor?.value || ''
    },
    setEditorText(text) {
      if (this.$refs.editor) {
        this.$refs.editor.value = text
      }
    },
    appendEditorText(text) {
      if (this.$refs.editor) {
        this.$refs.editor.value += text
      }
    },
    focusEditor() {
      this.$refs.editor?.focus()
    },
    getCaretWordInfo() {
      const textarea = this.$refs.editor
      if (!textarea) return {}
      const caretIndex = textarea.selectionStart
      const text = textarea.value
      let wordStart = caretIndex
      while (wordStart > 0 && /\S/.test(text[wordStart - 1])) {
        wordStart--
      }
      return {
        word: text.slice(wordStart, caretIndex),
        caretIndex
      }
    }
  }
}
</script>
