      return (this.items || []).filter(item =>
        this.internalSelected.includes(item.name)
      )
    },
    selectedItem() {
      if (!this.isSingleSelect || this.internalSelected.length === 0) return null
      return (this.items || []).find(item => item.name === this.internalSelected[0])
    },
    buttonTitle() {
      if (this.isSingleSelect && this.selectedItem) {
        return this.selectedItem.name
      }
      if (this.activeItems.length > 0) {
        return `${this.activeItems.length} item(s) selected`
      }
      return `Select ${this.label.toLowerCase()}`
    },
    selectedCountText() {
      if (this.isSingleSelect) {
        return this.selectedItem ? `Selected: ${this.selectedItem.name}` : 'None selected'
      }
      return `${this.internalSelected.length} item(s) selected`
    }
  },
  watch: {
    selectedItems: {
      handler(newVal) {
        this.internalSelected = newVal.map(item => typeof item === 'string' ? item : item.name)
      },
      deep: true
    }
  },
  mounted() {
    this.internalSelected = this.selectedItems.map(item => typeof item === 'string' ? item : item.name)
    document.addEventListener('click', this.handleDocumentClick)
  },
  unmounted() {
    document.removeEventListener('click', this.handleDocumentClick)
  },
  methods: {
    toggleGrid() {
      this.showGrid = !this.showGrid
      if (this.showGrid) {
        this.filterText = ''
      }
    },
    isItemSelected(itemName) {
      return this.internalSelected.includes(itemName)
    },
    selectItem(item) {
      if (this.isSingleSelect) {
        this.internalSelected = [item.name]
        this.showGrid = false
        this.$emit('update:selected-items', [item])
      } else {
        const index = this.internalSelected.indexOf(item.name)
        if (index > -1) {
          this.internalSelected.splice(index, 1)
        } else {
          this.internalSelected.push(item.name)
        }
        const updatedItems = (this.items || []).filter(i =>
          this.internalSelected.includes(i.name)
        )
        this.$emit('update:selected-items', updatedItems)
      }
    },
    handleDocumentClick(event) {
      if (!this.$el.contains(event.target)) {
        this.showGrid = false
      }
    }
  }
}
</script>
